<?php
namespace App\Http\Controllers;
use App\Models\Payment;use App\Models\YellowPageApplication;use App\Services\PaymentService;use Illuminate\Http\Request;use Illuminate\Support\Str;
class PaymentController extends Controller {private function owned(Request $r,YellowPageApplication $a){abort_unless($a->owner_key===$r->session()->get('yellow_pages_owner'),403);}public function initiate(Request $r,YellowPageApplication $application){$this->owned($r,$application);abort_unless($application->status==='payment_pending',422,'Application is not eligible for payment.');$p=Payment::firstOrCreate(['yellow_page_application_id'=>$application->id],['order_reference'=>'YPAY-'.strtoupper(Str::random(12)),'amount'=>$application->amount]);return ['payment'=>$p,'redirect_url'=>url('/?payment='.$application->id)];}public function status(Request $r,YellowPageApplication $application){$this->owned($r,$application);return $application->load('payment','receipt');}public function callback(Request $r,PaymentService $service){$secret=config('services.y_payment.callback_secret');abort_unless($secret&&hash_equals($secret,(string)$r->header('X-Gateway-Signature')),401,'Invalid payment callback signature.');$data=$r->validate(['order_reference'=>'required|string','status'=>'required|in:success,failed,cancelled','transaction_id'=>'nullable|string']);$payment=Payment::where('order_reference',$data['order_reference'])->firstOrFail();$service->verify($payment,$data);return ['ok'=>true];}}
